(() => {
  if (!window.__CDPX_CACHE) {
    window.__CDPX_CACHE = new Map();
  }
  window.__CDPX_CACHE.clear();

  const isInteractive = (el) => {
    const tag = el.tagName.toLowerCase();
    if (['a', 'button', 'input', 'select', 'textarea', 'summary'].includes(tag)) return true;
    if (el.hasAttribute('onclick') || el.getAttribute('role') === 'button' || el.getAttribute('role') === 'link') return true;
    try {
      const style = window.getComputedStyle(el);
      return style.cursor === 'pointer' && style.pointerEvents !== 'none';
    } catch (_) {
      return false;
    }
  };

  const getAccessibleName = (el) => {
    const aria = el.getAttribute('aria-label') || el.getAttribute('title') || el.getAttribute('placeholder');
    if (aria) return aria.trim();
    if (el.innerText) {
      const txt = el.innerText.trim().replace(/\s+/g, ' ');
      if (txt.length > 0) return txt.slice(0, 60);
    }
    return el.getAttribute('alt') || '';
  };

  const elements = [];
  const walker = document.createTreeWalker(document.body || document.documentElement, NodeFilter.SHOW_ELEMENT);
  let node;
  let idx = 1;
  const recordedNodes = [];

  while ((node = walker.nextNode())) {
    if (!isInteractive(node)) continue;

    // Filter out purely decorative sub-elements (svg, path, circle, span) if an ancestor interactive element is already captured
    const tag = node.tagName.toLowerCase();
    if (['svg', 'path', 'circle', 'span', 'i', 'g'].includes(tag)) {
      if (node.closest('a, button, [role="button"], [role="link"]')) {
        continue;
      }
    }

    let rect;
    try {
      rect = node.getBoundingClientRect();
    } catch (_) {
      continue;
    }

    // Viewport & visibility culling
    if (rect.width <= 0 || rect.height <= 0) continue;
    if (rect.bottom < 0 || rect.top > window.innerHeight || rect.right < 0 || rect.left > window.innerWidth) continue;

    // Occlusion hit-test
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    try {
      const topEl = document.elementFromPoint(cx, cy);
      if (topEl && !node.contains(topEl) && !topEl.contains(node)) continue;
    } catch (_) {}

    window.__CDPX_CACHE.set(idx, node);

    const role = node.getAttribute('role') || (tag === 'a' ? 'link' : tag);
    const name = getAccessibleName(node);

    elements.push({
      id: idx,
      tag: tag,
      role: role,
      name: name,
      value: node.value !== undefined ? String(node.value) : null,
      x: Math.round(cx),
      y: Math.round(cy),
      w: Math.round(rect.width),
      h: Math.round(rect.height)
    });
    idx++;
  }

  return {
    title: document.title || '',
    url: window.location.href,
    elements: elements
  };
})()